import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep, uniform, float, positionLocal, length, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, Shape, ExtrudeGeometry, PlaneGeometry, CylinderGeometry, DirectionalLight, AdditiveBlending, DoubleSide } = THREE;

  const root = new Group();
  root.name = 'feature-triptych';

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const ACCENT = colors.accent ?? '#ff2a38';
  const PAPER = colors.paper ?? '#e8ecf2';
  const GRAD0 = (colors.gradientStops && colors.gradientStops[0]?.hex) ?? '#191921';
  const GRAD1 = (colors.gradientStops && colors.gradientStops[1]?.hex) ?? '#121218';
  const BORDER = '#26262f';

  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  // ---------- STAGE BACKDROP (gradient, never flat void) ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(GRAD1), color(GRAD0), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- NODE-LOCAL RIM LIGHT (key is upper-left from scene) ----------
  const rim = new DirectionalLight(PAPER, 0.75);
  rim.position.set(3.2, -0.8, 2.5);
  root.add(rim);
  const accentRim = new DirectionalLight(ACCENT, 0.35);
  accentRim.position.set(-2.5, -2.0, 1.5);
  root.add(accentRim);

  // ---------- HELPERS ----------
  function roundedRectShape(w, h, r) {
    const s = new Shape();
    const hw = w / 2, hh = h / 2;
    s.moveTo(-hw + r, -hh);
    s.lineTo(hw - r, -hh);
    s.quadraticCurveTo(hw, -hh, hw, -hh + r);
    s.lineTo(hw, hh - r);
    s.quadraticCurveTo(hw, hh, hw - r, hh);
    s.lineTo(-hw + r, hh);
    s.quadraticCurveTo(-hw, hh, -hw, hh - r);
    s.lineTo(-hw, -hh + r);
    s.quadraticCurveTo(-hw, -hh, -hw + r, -hh);
    return s;
  }

  const CARD_W = 1.5, CARD_H = 1.9, GAP = 0.25, CARD_DEPTH = 0.04;
  const TEXT_SCALE = 0.01;

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  // Group into triads: glyph, title, body
  const cardsData = [];
  for (let i = 0; i < 3; i++) {
    cardsData.push({
      glyph: String(textItems[i * 3]?.text ?? ['01', '02', '03'][i]),
      title: String(textItems[i * 3 + 1]?.text ?? ''),
      body: String(textItems[i * 3 + 2]?.text ?? ''),
    });
  }

  const cardGroups = [];
  const hoverState = { current: -1 };

  // shared geometries
  const cardGeo = new ExtrudeGeometry(roundedRectShape(CARD_W, CARD_H, 0.06), {
    depth: CARD_DEPTH, bevelEnabled: true, bevelThickness: 0.008, bevelSize: 0.006, bevelSegments: 2, curveSegments: 10,
  });
  const borderGeo = new ExtrudeGeometry(roundedRectShape(CARD_W + 0.012, CARD_H + 0.012, 0.066), {
    depth: 0.01, bevelEnabled: false, curveSegments: 10,
  });
  const discGeo = new CylinderGeometry(0.2, 0.2, 0.05, 40);
  discGeo.rotateX(Math.PI / 2);
  const shadowGeo = new PlaneGeometry(1.35, 0.4);
  const glowGeo = new PlaneGeometry(0.34, 0.34);
  disposables.push(cardGeo, borderGeo, discGeo, shadowGeo, glowGeo);

  const totalW = CARD_W * 3 + GAP * 2; // 5.0
  const startX = -totalW / 2 + CARD_W / 2;

  for (let i = 0; i < 3; i++) {
    const data = cardsData[i];
    const card = new Group();
    card.userData.cardIndex = i;
    const baseX = startX + i * (CARD_W + GAP);
    card.position.set(baseX, 0.1, 0);
    card.userData.baseY = 0.1;
    card.userData.baseZ = 0;

    // card body — vertical albedo ramp
    const cardMat = new MeshPhysicalNodeMaterial({
      roughness: 0.6, metalness: 0.25, clearcoat: 0.15, clearcoatRoughness: 0.4,
    });
    const tY = positionLocal.y.add(CARD_H / 2).div(CARD_H).clamp(0, 1);
    cardMat.colorNode = mix(color(GRAD1), color(GRAD0), tY); // top = GRAD0
    const cardMesh = new Mesh(cardGeo, cardMat);
    cardMesh.userData.cardIndex = i;
    card.add(cardMesh);
    disposables.push(cardMat);

    // hairline border
    const borderMat = new MeshBasicNodeMaterial();
    borderMat.colorNode = color(BORDER);
    const borderMesh = new Mesh(borderGeo, borderMat);
    borderMesh.position.z = -0.011;
    borderMesh.userData.cardIndex = i;
    card.add(borderMesh);
    disposables.push(borderMat);

    // machined icon disc
    const discMat = new MeshPhysicalNodeMaterial({
      roughness: 0.55, metalness: 0.5, clearcoat: 0.2, clearcoatRoughness: 0.35,
    });
    if ('anisotropy' in discMat) discMat.anisotropy = 0.6;
    discMat.colorNode = color('#2a2a33');
    const disc = new Mesh(discGeo, discMat);
    disc.position.set(0, 0.375, CARD_DEPTH + 0.035);
    disc.userData.cardIndex = i;
    card.add(disc);
    disposables.push(discMat);

    // accent glow behind glyph (emissive read, animatable)
    const uGlow = uniform(0.55);
    const glowMat = new MeshBasicNodeMaterial({
      transparent: true, blending: AdditiveBlending, depthWrite: false,
    });
    const gd = length(uv().sub(vec2(0.5, 0.5))).mul(2.0);
    glowMat.colorNode = color(ACCENT).mul(uGlow);
    glowMat.opacityNode = float(1.0).sub(smoothstep(0.15, 0.95, gd));
    const glow = new Mesh(glowGeo, glowMat);
    glow.position.set(0, 0.375, CARD_DEPTH + 0.062);
    card.add(glow);
    disposables.push(glowMat);

    // glyph
    const glyphText = ctx.fontAtlas.createText(data.glyph, {
      fontSize: 20, color: ACCENT, align: 'center',
    });
    glyphText.scale.setScalar(TEXT_SCALE);
    glyphText.position.set(0, 0.375, CARD_DEPTH + 0.07);
    card.add(glyphText);

    // title — icon seat bottom at 0.175, gap 0.25 => title around y -0.06
    const titleText = ctx.fontAtlas.createText(data.title, {
      fontSize: 20, color: PAPER, align: 'center', maxWidthPx: 130,
    });
    titleText.scale.setScalar(TEXT_SCALE);
    titleText.position.set(0, -0.06, CARD_DEPTH + 0.02);
    card.add(titleText);

    // body — 0.125 gap below title
    const bodyText = ctx.fontAtlas.createText(data.body, {
      fontSize: 13, color: '#a9b0bc', align: 'center', maxWidthPx: 118,
    });
    bodyText.scale.setScalar(TEXT_SCALE);
    bodyText.position.set(0, -0.42, CARD_DEPTH + 0.02);
    card.add(bodyText);

    // contact shadow (widens/softens on lift)
    const uShadow = uniform(0.5);
    const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
    shadowMat.colorNode = color('#000000');
    const sd = length(uv().sub(vec2(0.5, 0.5)).mul(vec2(2.0, 2.0)));
    shadowMat.opacityNode = float(1.0).sub(smoothstep(0.1, 1.0, sd)).mul(uShadow);
    shadowMat.side = DoubleSide;
    const shadow = new Mesh(shadowGeo, shadowMat);
    shadow.position.set(0, -(CARD_H / 2) - 0.12, -0.06);
    root.add(shadow);
    disposables.push(shadowMat);
    shadow.position.x = baseX;
    shadow.position.y = -(CARD_H / 2) + 0.1 - 0.12;

    card.userData.uGlow = uGlow;
    card.userData.uShadow = uShadow;
    card.userData.shadow = shadow;

    root.add(card);
    cardGroups.push(card);
  }

  // ---------- ENTRANCE: stagger-cards / fade-up ----------
  const entrance = gsap.timeline();
  timelines.push(entrance);
  cardGroups.forEach((card, i) => {
    const mats = [];
    card.traverse((o) => {
      if (o.material) {
        const arr = Array.isArray(o.material) ? o.material : [o.material];
        for (const m of arr) {
          m.transparent = true;
          if (m.opacity === undefined || m.opacity === null) m.opacity = 1;
          mats.push(m);
        }
      }
    });
    const targetOpacities = mats.map((m) => m.opacity);
    mats.forEach((m) => { m.opacity = 0; });
    card.userData.shadow.userData = card.userData.shadow.userData || {};
    const uS = card.userData.uShadow;
    const shadowTarget = uS.value;
    uS.value = 0;

    const baseY = card.userData.baseY;
    card.position.y = baseY + 0.2;

    entrance.to(card.position, { y: baseY, duration: 0.5, ease: 'power2.out' }, i * 0.08);
    mats.forEach((m, mi) => {
      entrance.to(m, { opacity: targetOpacities[mi], duration: 0.5, ease: 'power2.out' }, i * 0.08);
    });
    entrance.to(uS, { value: shadowTarget, duration: 0.5, ease: 'power2.out' }, i * 0.08);
  });
  // weighted settle on the row
  root.scale.setScalar(1.0);
  entrance.fromTo(root.scale, { x: 1.0, y: 1.0, z: 1.0 }, { x: 1.0, y: 1.0, z: 1.0, duration: 0.01 }, 0);

  // ---------- HOVER LIFT ----------
  function liftCard(i) {
    if (hoverState.current === i) return;
    dropCard(hoverState.current);
    hoverState.current = i;
    const card = cardGroups[i];
    if (!card) return;
    gsap.to(card.position, {
      y: card.userData.baseY + 0.06, z: card.userData.baseZ + 0.12,
      duration: 0.18, ease: 'power2.out',
    });
    gsap.to(card.userData.uGlow, { value: 0.85, duration: 0.18, ease: 'power2.out' });
    gsap.to(card.userData.shadow.scale, { x: 1.2, y: 1.25, duration: 0.18, ease: 'power2.out' });
    gsap.to(card.userData.uShadow, { value: 0.32, duration: 0.18, ease: 'power2.out' });
  }

  function dropCard(i) {
    if (i < 0) return;
    const card = cardGroups[i];
    if (!card) return;
    gsap.to(card.position, {
      y: card.userData.baseY, z: card.userData.baseZ,
      duration: 0.3, ease: 'power3.out',
    });
    gsap.to(card.userData.uGlow, { value: 0.55, duration: 0.3, ease: 'power3.out' });
    gsap.to(card.userData.shadow.scale, { x: 1.0, y: 1.0, duration: 0.3, ease: 'power3.out' });
    gsap.to(card.userData.uShadow, { value: 0.5, duration: 0.3, ease: 'power3.out' });
    if (hoverState.current === i) hoverState.current = -1;
  }

  function findCardIndex(obj) {
    let o = obj;
    while (o) {
      if (o.userData && o.userData.cardIndex !== undefined) return o.userData.cardIndex;
      o = o.parent;
    }
    return -1;
  }

  root.userData.handlers = {
    pointerover: (ev) => {
      const idx = findCardIndex(ev?.object ?? ev?.target ?? null);
      if (idx >= 0) liftCard(idx);
    },
    pointermove: (ev) => {
      const idx = findCardIndex(ev?.object ?? ev?.target ?? null);
      if (idx >= 0) liftCard(idx);
      else if (hoverState.current >= 0) dropCard(hoverState.current);
    },
    pointerout: () => {
      if (hoverState.current >= 0) dropCard(hoverState.current);
    },
  };

  // ---------- PRIMITIVES FROM CONFIG ----------
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    if (ctx.primitives && ctx.primitives[p.name]) {
      const h = ctx.primitives[p.name](root, p.params ?? {});
      if (h) primitiveHandles.push(h);
    }
  }

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    gsap.killTweensOf(root.scale);
    cardGroups.forEach((c) => {
      gsap.killTweensOf(c.position);
      gsap.killTweensOf(c.userData.uGlow);
      gsap.killTweensOf(c.userData.uShadow);
      gsap.killTweensOf(c.userData.shadow.scale);
    });
    primitiveHandles.forEach((h) => h.cleanup && h.cleanup());
    disposables.forEach((d) => d.dispose && d.dispose());
    root.traverse((o) => {
      if (o.geometry && !disposables.includes(o.geometry)) o.geometry.dispose && o.geometry.dispose();
    });
  };

  return root;
}
